        "الكحة الجافة من أشيع الـ<bdi>symptoms</bdi> الجانبية لمثبطات الإنزيم المحول، وسببها تراكم البراديكينين، وهذا التأثير غير موجود مع حاصرات المستقبلات.",
        "حاصرات بيتا والمدرات الثيازيدية وحاصرات قنوات الكالسيوم أدوية ضغط فعالة بس ما تعطي نفس الحماية الكلوية النوعية ضد البروتين البولي عند مرضى <bdi>diabetes</bdi>.",
